BEGIN;

CREATE TABLE IF NOT EXISTS public.schema_migrations (
  name TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());

-- ┌─── 001_init.sql ───
-- 001_init.sql — core schema: users, valleys, reports
-- On Supabase, extensions live in the `extensions` schema (already on the search_path).
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_namespace WHERE nspname = 'extensions') THEN
    CREATE EXTENSION IF NOT EXISTS postgis WITH SCHEMA extensions;
  ELSE
    CREATE EXTENSION IF NOT EXISTS postgis;
  END IF;
END $$;

-- ───────────── users ─────────────
CREATE TABLE IF NOT EXISTS public.users (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  email           TEXT NOT NULL UNIQUE,
  password_hash   TEXT NOT NULL,
  display_name    TEXT,
  role            TEXT NOT NULL DEFAULT 'reporter' CHECK (role IN ('reporter', 'admin')),
  -- Trust score is maintained by triggers in 002_verification.sql
  trust_score     NUMERIC(4,3) NOT NULL DEFAULT 0.500 CHECK (trust_score BETWEEN 0 AND 1),
  verified_count  INTEGER NOT NULL DEFAULT 0,
  rejected_count  INTEGER NOT NULL DEFAULT 0,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ───────────── valleys (wadis / drainage channels) ─────────────
CREATE TABLE IF NOT EXISTS public.valleys (
  id       SERIAL PRIMARY KEY,
  name_ar  TEXT NOT NULL,
  name_en  TEXT,
  geom     GEOMETRY(MultiLineString, 4326) NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_valleys_geom ON public.valleys USING GIST (geom);

-- ───────────── reports ─────────────
CREATE TABLE IF NOT EXISTS public.reports (
  id           BIGSERIAL PRIMARY KEY,
  user_id      UUID REFERENCES public.users(id) ON DELETE SET NULL,
  title        TEXT NOT NULL CHECK (char_length(title) BETWEEN 3 AND 200),
  description  TEXT CHECK (char_length(description) <= 2000),
  intensity    SMALLINT NOT NULL CHECK (intensity BETWEEN 1 AND 5),
  status       TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'verified', 'rejected')),
  geom         GEOMETRY(Point, 4326) NOT NULL,
  reviewed_by  UUID REFERENCES public.users(id) ON DELETE SET NULL,
  reviewed_at  TIMESTAMPTZ,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_reports_geom           ON public.reports USING GIST (geom);
CREATE INDEX IF NOT EXISTS idx_reports_status_created ON public.reports (status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_reports_user           ON public.reports (user_id);

CREATE OR REPLACE FUNCTION public.fn_touch_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS trg_reports_touch ON public.reports;
CREATE TRIGGER trg_reports_touch BEFORE UPDATE ON public.reports
  FOR EACH ROW EXECUTE FUNCTION public.fn_touch_updated_at();
INSERT INTO public.schema_migrations (name) VALUES ('001_init.sql') ON CONFLICT DO NOTHING;

-- ┌─── 002_verification.sql ───
-- 002_verification.sql — anti-fraud / verification engine
--
-- Every report gets a confidence score (0–100) built from three signals:
--   1. Valley proximity   — is the report on/near a mapped wadi?        (weight_valley)
--   2. Corroboration      — independent reports nearby in time & space? (weight_corroboration)
--   3. Reporter trust     — how accurate has this user been historically? (weight_trust)
-- Reports at or above auto_verify_threshold are auto-verified.
-- Only MANUAL admin decisions feed back into the trust score (avoids feedback loops).

-- ───────────── tunables (single-row config) ─────────────
CREATE TABLE IF NOT EXISTS public.verification_config (
  id                        BOOLEAN PRIMARY KEY DEFAULT TRUE CHECK (id),
  valley_buffer_m           INTEGER NOT NULL DEFAULT 500,   -- full valley score inside this distance
  valley_falloff_m          INTEGER NOT NULL DEFAULT 1500,  -- score decays linearly to 0 at buffer + falloff
  corroboration_radius_m    INTEGER NOT NULL DEFAULT 1000,
  corroboration_window_min  INTEGER NOT NULL DEFAULT 60,
  corroboration_saturation  INTEGER NOT NULL DEFAULT 4,     -- this many independent reports = full score
  weight_valley             NUMERIC NOT NULL DEFAULT 40,
  weight_corroboration      NUMERIC NOT NULL DEFAULT 35,
  weight_trust              NUMERIC NOT NULL DEFAULT 25,
  anonymous_trust           NUMERIC NOT NULL DEFAULT 0.300,
  auto_verify_threshold     NUMERIC NOT NULL DEFAULT 80,
  trust_prior_alpha         NUMERIC NOT NULL DEFAULT 2,     -- Bayesian prior: 2 verified …
  trust_prior_beta          NUMERIC NOT NULL DEFAULT 2,     -- … and 2 rejected → new users start at 0.5
  cluster_alert_min_reports INTEGER NOT NULL DEFAULT 5
);
INSERT INTO public.verification_config DEFAULT VALUES ON CONFLICT DO NOTHING;

-- ───────────── new report columns ─────────────
ALTER TABLE public.reports
  ADD COLUMN IF NOT EXISTS valley_id           INTEGER REFERENCES public.valleys(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS valley_distance_m   NUMERIC(10,1),
  ADD COLUMN IF NOT EXISTS corroboration_count INTEGER NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS confidence_score    NUMERIC(5,2),
  ADD COLUMN IF NOT EXISTS auto_verified       BOOLEAN NOT NULL DEFAULT FALSE;

CREATE INDEX IF NOT EXISTS idx_reports_confidence ON public.reports (status, confidence_score DESC NULLS LAST);
CREATE INDEX IF NOT EXISTS idx_reports_created    ON public.reports (created_at);

-- ───────────── scoring ─────────────
-- Scores one report, persists the result, and auto-verifies it if it crosses the threshold.
CREATE OR REPLACE FUNCTION public.fn_score_report(p_report_id BIGINT)
RETURNS public.reports
LANGUAGE plpgsql AS $$
DECLARE
  cfg        public.verification_config%ROWTYPE;
  r          public.reports%ROWTYPE;
  v_id       INTEGER;
  v_dist     DOUBLE PRECISION;
  v_corr     INTEGER;
  v_trust    NUMERIC;
  f_valley   NUMERIC;
  f_corr     NUMERIC;
  v_score    NUMERIC;
BEGIN
  SELECT * INTO cfg FROM public.verification_config LIMIT 1;
  SELECT * INTO r   FROM public.reports WHERE id = p_report_id FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;

  -- 1) nearest valley (index-assisted KNN, then exact geodesic distance)
  SELECT v.id, ST_Distance(v.geom::geography, r.geom::geography)
    INTO v_id, v_dist
  FROM public.valleys v
  ORDER BY v.geom <-> r.geom
  LIMIT 1;

  IF v_dist IS NULL THEN
    f_valley := 0;
  ELSIF v_dist <= cfg.valley_buffer_m THEN
    f_valley := 1;
  ELSE
    f_valley := GREATEST(0, 1 - (v_dist - cfg.valley_buffer_m) / NULLIF(cfg.valley_falloff_m, 0));
  END IF;

  -- 2) corroboration: distinct independent reporters nearby within ± window, excluding
  --    rejected reports and the reporter themself. Anonymous reports each count once.
  SELECT COUNT(DISTINCT COALESCE(o.user_id::text, 'anon-' || o.id))
    INTO v_corr
  FROM public.reports o
  WHERE o.id <> r.id
    AND o.status <> 'rejected'
    AND (r.user_id IS NULL OR o.user_id IS DISTINCT FROM r.user_id)
    AND o.created_at BETWEEN r.created_at - make_interval(mins => cfg.corroboration_window_min)
                         AND r.created_at + make_interval(mins => cfg.corroboration_window_min)
    AND ST_DWithin(o.geom::geography, r.geom::geography, cfg.corroboration_radius_m);

  f_corr := LEAST(v_corr, cfg.corroboration_saturation)::NUMERIC / cfg.corroboration_saturation;

  -- 3) reporter trust
  IF r.user_id IS NULL THEN
    v_trust := cfg.anonymous_trust;
  ELSE
    SELECT trust_score INTO v_trust FROM public.users WHERE id = r.user_id;
    v_trust := COALESCE(v_trust, cfg.anonymous_trust);
  END IF;

  v_score := ROUND(
      cfg.weight_valley        * f_valley
    + cfg.weight_corroboration * f_corr
    + cfg.weight_trust         * v_trust, 2);

  UPDATE public.reports SET
    valley_id           = CASE WHEN f_valley > 0 THEN v_id END,
    valley_distance_m   = ROUND(v_dist::NUMERIC, 1),
    corroboration_count = v_corr,
    confidence_score    = v_score,
    status        = CASE WHEN status = 'pending' AND v_score >= cfg.auto_verify_threshold
                         THEN 'verified' ELSE status END,
    auto_verified = auto_verified OR (status = 'pending' AND v_score >= cfg.auto_verify_threshold)
  WHERE id = r.id
  RETURNING * INTO r;

  RETURN r;
END $$;

-- Scores a new report and re-scores pending neighbours whose corroboration just changed.
-- Returns every report that was (re)scored so the API can broadcast the changes.
CREATE OR REPLACE FUNCTION public.fn_process_report(p_report_id BIGINT)
RETURNS SETOF public.reports
LANGUAGE plpgsql AS $$
DECLARE
  cfg public.verification_config%ROWTYPE;
  src public.reports%ROWTYPE;
  nid BIGINT;
BEGIN
  SELECT * INTO cfg FROM public.verification_config LIMIT 1;
  SELECT * INTO src FROM public.reports WHERE id = p_report_id;
  IF NOT FOUND THEN RETURN; END IF;

  RETURN NEXT public.fn_score_report(p_report_id);

  FOR nid IN
    SELECT o.id FROM public.reports o
    WHERE o.id <> src.id
      AND o.status = 'pending'
      AND o.created_at BETWEEN src.created_at - make_interval(mins => cfg.corroboration_window_min)
                           AND src.created_at + make_interval(mins => cfg.corroboration_window_min)
      AND ST_DWithin(o.geom::geography, src.geom::geography, cfg.corroboration_radius_m)
    ORDER BY o.id
  LOOP
    RETURN NEXT public.fn_score_report(nid);
  END LOOP;
END $$;

-- ───────────── trust score feedback ─────────────
-- Fires when an ADMIN reviews a report (reviewed_by set). Auto-verifications don't count.
CREATE OR REPLACE FUNCTION public.fn_update_trust() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  cfg public.verification_config%ROWTYPE;
  dv  INTEGER := 0;
  dr  INTEGER := 0;
BEGIN
  -- Only act on a manual decision: an admin is set AND (status changed OR first manual review,
  -- e.g. an admin confirming a report that was auto-verified).
  IF NEW.user_id IS NULL OR NEW.reviewed_by IS NULL
     OR (NEW.status = OLD.status AND OLD.reviewed_by IS NOT NULL) THEN
    RETURN NEW;
  END IF;

  -- Undo the previous manual decision, if there was one (admin changed their mind)
  IF OLD.reviewed_by IS NOT NULL THEN
    IF OLD.status = 'verified' THEN dv := dv - 1; END IF;
    IF OLD.status = 'rejected' THEN dr := dr - 1; END IF;
  END IF;
  IF NEW.status = 'verified' THEN dv := dv + 1; END IF;
  IF NEW.status = 'rejected' THEN dr := dr + 1; END IF;

  SELECT * INTO cfg FROM public.verification_config LIMIT 1;

  UPDATE public.users u SET
    verified_count = GREATEST(0, u.verified_count + dv),
    rejected_count = GREATEST(0, u.rejected_count + dr),
    trust_score = ROUND(
      (GREATEST(0, u.verified_count + dv) + cfg.trust_prior_alpha)
      / (GREATEST(0, u.verified_count + dv) + GREATEST(0, u.rejected_count + dr)
         + cfg.trust_prior_alpha + cfg.trust_prior_beta), 3)
  WHERE u.id = NEW.user_id;

  RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS trg_reports_trust ON public.reports;
CREATE TRIGGER trg_reports_trust AFTER UPDATE OF status, reviewed_by ON public.reports
  FOR EACH ROW EXECUTE FUNCTION public.fn_update_trust();

-- ───────────── live clusters ─────────────
-- DBSCAN over recent non-rejected reports, in UTM 38N metres (covers central KSA;
-- distortion elsewhere in the Kingdom is small enough for ~1 km clustering).
CREATE OR REPLACE FUNCTION public.fn_active_clusters(p_window_min INTEGER DEFAULT NULL)
RETURNS TABLE (
  cluster_key     TEXT,
  report_count    INTEGER,
  reporter_count  INTEGER,
  max_intensity   SMALLINT,
  avg_confidence  NUMERIC,
  valley_name_ar  TEXT,
  first_seen      TIMESTAMPTZ,
  last_seen       TIMESTAMPTZ,
  lng             DOUBLE PRECISION,
  lat             DOUBLE PRECISION
)
LANGUAGE sql STABLE AS $$
  WITH cfg AS (SELECT * FROM public.verification_config LIMIT 1),
  recent AS (
    SELECT r.*,
           ST_ClusterDBSCAN(ST_Transform(r.geom, 32638), eps => cfg.corroboration_radius_m, minpoints => 2)
             OVER () AS cid
    FROM public.reports r, cfg
    WHERE r.status <> 'rejected'
      AND r.created_at >= now() - make_interval(mins => COALESCE(p_window_min, cfg.corroboration_window_min))
  )
  SELECT
    -- stable-ish key: the oldest report id in the cluster
    'c' || MIN(id)                                                  AS cluster_key,
    COUNT(*)::INT                                                   AS report_count,
    COUNT(DISTINCT COALESCE(user_id::text, 'anon-' || id))::INT     AS reporter_count,
    MAX(intensity)                                                  AS max_intensity,
    ROUND(AVG(confidence_score), 1)                                 AS avg_confidence,
    (SELECT v.name_ar FROM public.valleys v
      WHERE v.id = mode() WITHIN GROUP (ORDER BY recent.valley_id)) AS valley_name_ar,
    MIN(created_at), MAX(created_at),
    ST_X(ST_Centroid(ST_Collect(geom))), ST_Y(ST_Centroid(ST_Collect(geom)))
  FROM recent
  WHERE cid IS NOT NULL
  GROUP BY cid
  ORDER BY COUNT(*) DESC;
$$;
INSERT INTO public.schema_migrations (name) VALUES ('002_verification.sql') ON CONFLICT DO NOTHING;

-- ┌─── 003_tiles.sql ───
-- 003_tiles.sql — Martin function source for public, verified reports.
-- Exposes only safe columns (no user_id, no description) to the public map.
CREATE OR REPLACE FUNCTION public.verified_reports_tiles(z INTEGER, x INTEGER, y INTEGER, query_params JSON DEFAULT '{}'::JSON)
RETURNS BYTEA
LANGUAGE sql STABLE PARALLEL SAFE AS $$
  SELECT ST_AsMVT(t, 'verified_reports', 4096, 'geom')
  FROM (
    SELECT r.id, r.title, r.intensity, r.confidence_score,
           EXTRACT(EPOCH FROM r.created_at)::BIGINT AS created_ts,
           ST_AsMVTGeom(ST_Transform(r.geom, 3857), ST_TileEnvelope(z, x, y), 4096, 64, TRUE) AS geom
    FROM public.reports r
    WHERE r.status = 'verified'
      AND r.created_at >= now() - INTERVAL '48 hours'
      AND r.geom && ST_Transform(ST_TileEnvelope(z, x, y), 4326)
  ) t;
$$;
INSERT INTO public.schema_migrations (name) VALUES ('003_tiles.sql') ON CONFLICT DO NOTHING;

-- ┌─── 004_lockdown.sql ───
-- 004_lockdown.sql — close the database to everything except the backend & Martin.
--
-- Supabase publishes every table in `public` through its REST API (PostgREST) to the
-- `anon` and `authenticated` roles. This app never uses that API: all access goes
-- through the Express backend and Martin, which connect as the database owner.
-- Without this migration, anyone holding the public anon key could read
-- users.password_hash or call fn_score_report directly.
--
-- Safe on plain PostgreSQL too: role-specific statements are skipped when the
-- Supabase roles do not exist.

-- 1) RLS on every table with NO policies → API roles see nothing.
--    The table owner (postgres, used by the backend and Martin) bypasses RLS.
ALTER TABLE public.users               ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.reports             ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.valleys             ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.verification_config ENABLE ROW LEVEL SECURITY;
ALTER TABLE IF EXISTS public.schema_migrations ENABLE ROW LEVEL SECURITY;

-- 2) Functions are executable by PUBLIC by default — revoke.
REVOKE EXECUTE ON FUNCTION public.fn_score_report(BIGINT)       FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_process_report(BIGINT)     FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_active_clusters(INTEGER)   FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.verified_reports_tiles(INTEGER, INTEGER, INTEGER, JSON) FROM PUBLIC;

-- 3) Belt and braces for Supabase's API roles (grants, not just RLS).
DO $$
DECLARE
  r TEXT;
BEGIN
  FOREACH r IN ARRAY ARRAY['anon', 'authenticated'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
      EXECUTE format('REVOKE ALL ON ALL TABLES    IN SCHEMA public FROM %I', r);
      EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM %I', r);
      EXECUTE format('REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM %I', r);
      EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON TABLES    FROM %I', r);
      EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON SEQUENCES FROM %I', r);
      EXECUTE format('ALTER DEFAULT PRIVILEGES IN SCHEMA public REVOKE ALL ON FUNCTIONS FROM %I', r);
    END IF;
  END LOOP;
END $$;
INSERT INTO public.schema_migrations (name) VALUES ('004_lockdown.sql') ON CONFLICT DO NOTHING;

-- ┌─── 005_valley_sources.sql ───
-- 005_valley_sources.sql — track where each valley came from, so imports can
-- upsert in place (keeping reports.valley_id links) instead of wiping the table.
ALTER TABLE public.valleys
  ADD COLUMN IF NOT EXISTS source     TEXT NOT NULL DEFAULT 'manual',   -- manual | sample | osm
  ADD COLUMN IF NOT EXISTS source_key TEXT,                             -- e.g. osm:way:123456
  ADD COLUMN IF NOT EXISTS waterway   TEXT,                             -- wadi | river | stream
  ADD COLUMN IF NOT EXISTS osm_ids    BIGINT[],
  ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT now();

-- Many small wadis in OSM have no name; they still matter for proximity scoring.
ALTER TABLE public.valleys ALTER COLUMN name_ar DROP NOT NULL;

CREATE UNIQUE INDEX IF NOT EXISTS idx_valleys_source_key ON public.valleys (source_key);

-- Mark the development seed rows so they can be removed once real data is loaded.
UPDATE public.valleys SET source = 'sample'
WHERE source = 'manual' AND name_en IN ('Wadi Hanifah', 'Wadi Fatimah', 'Wadi Baysh');
INSERT INTO public.schema_migrations (name) VALUES ('005_valley_sources.sql') ON CONFLICT DO NOTHING;

-- ┌─── 006_forecast.sql ───
-- 006_forecast.sql — weather + terrain flood forecasting.
--
-- Static terrain products (from analysis/terrain.py):
--   regions, rain_points, streams (channel reaches), catchments, flood_zones, stream_rain_weights
-- Forecast products (from analysis/forecast.py, hourly):
--   forecast_runs, forecast_rain, stream_forecasts (risky hours only), stream_forecast_summary

CREATE TABLE IF NOT EXISTS public.regions (
  id         SERIAL PRIMARY KEY,
  slug       TEXT NOT NULL UNIQUE,
  name_ar    TEXT NOT NULL,
  bbox       GEOMETRY(Polygon, 4326) NOT NULL,
  meta       JSONB NOT NULL DEFAULT '{}',
  loaded_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS public.rain_points (
  id         BIGSERIAL PRIMARY KEY,
  region_id  INTEGER NOT NULL REFERENCES public.regions(id) ON DELETE CASCADE,
  local_id   INTEGER NOT NULL,
  geom       GEOMETRY(Point, 4326) NOT NULL,
  UNIQUE (region_id, local_id)
);

CREATE TABLE IF NOT EXISTS public.streams (
  id              BIGSERIAL PRIMARY KEY,
  region_id       INTEGER NOT NULL REFERENCES public.regions(id) ON DELETE CASCADE,
  local_id        INTEGER NOT NULL,
  downstream_id   BIGINT REFERENCES public.streams(id) ON DELETE SET NULL,
  geom            GEOMETRY(LineString, 4326) NOT NULL,
  upstream_km2    NUMERIC(10,3) NOT NULL,   -- total area draining to the reach outlet
  local_km2       NUMERIC(10,4) NOT NULL,   -- area draining directly to this reach
  tc_h            NUMERIC(6,2)  NOT NULL,   -- time of concentration (Kirpich)
  relief_m        NUMERIC(8,1),
  cn_up           NUMERIC(5,2)  NOT NULL,   -- area-weighted SCS curve number upstream
  truncated       BOOLEAN NOT NULL DEFAULT FALSE, -- upstream basin extends beyond the region
  zone_km2        NUMERIC(10,4) NOT NULL DEFAULT 0,  -- flood-prone (HAND) area along the reach
  zone_built_km2  NUMERIC(10,4) NOT NULL DEFAULT 0,  -- built-up land inside that zone
  valley_id       INTEGER REFERENCES public.valleys(id) ON DELETE SET NULL, -- named wadi, if matched
  UNIQUE (region_id, local_id)
);
CREATE INDEX IF NOT EXISTS idx_streams_geom ON public.streams USING GIST (geom);
CREATE INDEX IF NOT EXISTS idx_streams_upstream ON public.streams (region_id, upstream_km2 DESC);

CREATE TABLE IF NOT EXISTS public.catchments (
  stream_id      BIGINT PRIMARY KEY REFERENCES public.streams(id) ON DELETE CASCADE,
  geom           GEOMETRY(MultiPolygon, 4326) NOT NULL,
  area_km2       NUMERIC(10,4) NOT NULL,
  cn             NUMERIC(5,2) NOT NULL,
  slope          NUMERIC(6,4),
  rain_point_id  BIGINT REFERENCES public.rain_points(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_catchments_geom ON public.catchments USING GIST (geom);

CREATE TABLE IF NOT EXISTS public.flood_zones (
  stream_id     BIGINT PRIMARY KEY REFERENCES public.streams(id) ON DELETE CASCADE,
  geom          GEOMETRY(MultiPolygon, 4326) NOT NULL,
  area_km2      NUMERIC(10,4) NOT NULL,
  built_up_km2  NUMERIC(10,4) NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_flood_zones_geom ON public.flood_zones USING GIST (geom);

-- For each reach: how much of its upstream area each rain point represents.
CREATE TABLE IF NOT EXISTS public.stream_rain_weights (
  stream_id      BIGINT NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
  rain_point_id  BIGINT NOT NULL REFERENCES public.rain_points(id) ON DELETE CASCADE,
  area_km2       NUMERIC(10,5) NOT NULL,
  PRIMARY KEY (stream_id, rain_point_id)
);

-- ───────────── forecasts ─────────────
CREATE TABLE IF NOT EXISTS public.forecast_runs (
  id          BIGSERIAL PRIMARY KEY,
  region_id   INTEGER NOT NULL REFERENCES public.regions(id) ON DELETE CASCADE,
  kind        TEXT NOT NULL CHECK (kind IN ('forecast', 'archive', 'scenario')),
  label       TEXT,
  source      TEXT NOT NULL,              -- e.g. open-meteo:best_match
  start_time  TIMESTAMPTZ NOT NULL,
  end_time    TIMESTAMPTZ NOT NULL,
  params      JSONB NOT NULL DEFAULT '{}',
  max_level   SMALLINT NOT NULL DEFAULT 1,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_forecast_runs_latest ON public.forecast_runs (region_id, kind, created_at DESC);

CREATE TABLE IF NOT EXISTS public.forecast_rain (
  run_id         BIGINT NOT NULL REFERENCES public.forecast_runs(id) ON DELETE CASCADE,
  rain_point_id  BIGINT NOT NULL REFERENCES public.rain_points(id) ON DELETE CASCADE,
  valid_time     TIMESTAMPTZ NOT NULL,
  precip_mm      REAL NOT NULL,
  PRIMARY KEY (run_id, rain_point_id, valid_time)
);

-- Only hours with level ≥ 2 are stored; absent hours mean level 1 (no significant risk).
CREATE TABLE IF NOT EXISTS public.stream_forecasts (
  run_id      BIGINT NOT NULL REFERENCES public.forecast_runs(id) ON DELETE CASCADE,
  stream_id   BIGINT NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
  valid_time  TIMESTAMPTZ NOT NULL,   -- expected time of peak flow
  rain_mm     REAL NOT NULL,          -- basin-average rain over the critical window
  runoff_mm   REAL NOT NULL,
  peak_m3s    REAL NOT NULL,
  level       SMALLINT NOT NULL CHECK (level BETWEEN 1 AND 5),
  PRIMARY KEY (run_id, stream_id, valid_time)
);
CREATE INDEX IF NOT EXISTS idx_stream_forecasts_time ON public.stream_forecasts (run_id, valid_time);

CREATE TABLE IF NOT EXISTS public.stream_forecast_summary (
  run_id          BIGINT NOT NULL REFERENCES public.forecast_runs(id) ON DELETE CASCADE,
  stream_id       BIGINT NOT NULL REFERENCES public.streams(id) ON DELETE CASCADE,
  max_level       SMALLINT NOT NULL,
  max_peak_m3s    REAL NOT NULL,
  max_runoff_mm   REAL NOT NULL,
  time_of_max     TIMESTAMPTZ,
  first_level3_at TIMESTAMPTZ,
  PRIMARY KEY (run_id, stream_id)
);
CREATE INDEX IF NOT EXISTS idx_summary_level ON public.stream_forecast_summary (run_id, max_level DESC);

-- ───────────── forecast as a report-verification signal ─────────────
-- Highest forecast level among reaches within `radius_m` of a point, ±3 h around `at`,
-- from the newest real forecast (not scenarios) covering that time. NULL = no forecast.
CREATE OR REPLACE FUNCTION public.fn_forecast_level_at(p_geom GEOMETRY, p_at TIMESTAMPTZ, p_radius_m INTEGER DEFAULT 1000)
RETURNS SMALLINT
LANGUAGE sql STABLE AS $$
  WITH run AS (
    SELECT fr.id FROM public.forecast_runs fr
    JOIN public.regions rg ON rg.id = fr.region_id
    WHERE fr.kind IN ('forecast', 'archive')
      AND p_at BETWEEN fr.start_time AND fr.end_time
      AND ST_Intersects(rg.bbox, p_geom)
    ORDER BY fr.created_at DESC
    LIMIT 1
  )
  SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM run) THEN NULL
              ELSE COALESCE((
                SELECT MAX(sf.level) FROM public.stream_forecasts sf
                JOIN public.streams s ON s.id = sf.stream_id
                WHERE sf.run_id = (SELECT id FROM run)
                  AND sf.valid_time BETWEEN p_at - INTERVAL '3 hours' AND p_at + INTERVAL '3 hours'
                  AND ST_DWithin(s.geom::geography, p_geom::geography, p_radius_m)), 1)
         END::SMALLINT;
$$;

ALTER TABLE public.verification_config
  ADD COLUMN IF NOT EXISTS weight_forecast NUMERIC NOT NULL DEFAULT 25;
-- Rebalance: the forecast now carries a quarter of the score. Weights still sum to 100.
UPDATE public.verification_config SET weight_valley = 30, weight_corroboration = 30, weight_trust = 15, weight_forecast = 25
WHERE weight_valley = 40 AND weight_corroboration = 35 AND weight_trust = 25;

ALTER TABLE public.reports ADD COLUMN IF NOT EXISTS forecast_level SMALLINT;

-- Same as 002's fn_score_report, plus: (a) proximity also counts terrain-derived channels
-- (≥ 5 km² upstream), (b) the forecast risk at the report's place and time.
-- Outside any forecast region the forecast weight is redistributed proportionally.
CREATE OR REPLACE FUNCTION public.fn_score_report(p_report_id BIGINT)
RETURNS public.reports
LANGUAGE plpgsql AS $$
DECLARE
  cfg        public.verification_config%ROWTYPE;
  r          public.reports%ROWTYPE;
  v_id       INTEGER;
  v_dist     DOUBLE PRECISION;
  s_dist     DOUBLE PRECISION;
  s_valley   INTEGER;
  v_corr     INTEGER;
  v_trust    NUMERIC;
  v_level    SMALLINT;
  f_valley   NUMERIC;
  f_corr     NUMERIC;
  f_fc       NUMERIC;
  w_sum      NUMERIC;
  v_score    NUMERIC;
BEGIN
  SELECT * INTO cfg FROM public.verification_config LIMIT 1;
  SELECT * INTO r   FROM public.reports WHERE id = p_report_id FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;

  SELECT v.id, ST_Distance(v.geom::geography, r.geom::geography) INTO v_id, v_dist
  FROM public.valleys v ORDER BY v.geom <-> r.geom LIMIT 1;

  SELECT ST_Distance(s.geom::geography, r.geom::geography), s.valley_id INTO s_dist, s_valley
  FROM public.streams s WHERE s.upstream_km2 >= 5 ORDER BY s.geom <-> r.geom LIMIT 1;

  IF s_dist IS NOT NULL AND (v_dist IS NULL OR s_dist < v_dist) THEN
    v_dist := s_dist;
    v_id := s_valley;   -- the named wadi this channel was matched to, if any
  END IF;

  IF v_dist IS NULL THEN
    f_valley := 0;
  ELSIF v_dist <= cfg.valley_buffer_m THEN
    f_valley := 1;
  ELSE
    f_valley := GREATEST(0, 1 - (v_dist - cfg.valley_buffer_m) / NULLIF(cfg.valley_falloff_m, 0));
  END IF;

  SELECT COUNT(DISTINCT COALESCE(o.user_id::text, 'anon-' || o.id)) INTO v_corr
  FROM public.reports o
  WHERE o.id <> r.id
    AND o.status <> 'rejected'
    AND (r.user_id IS NULL OR o.user_id IS DISTINCT FROM r.user_id)
    AND o.created_at BETWEEN r.created_at - make_interval(mins => cfg.corroboration_window_min)
                         AND r.created_at + make_interval(mins => cfg.corroboration_window_min)
    AND ST_DWithin(o.geom::geography, r.geom::geography, cfg.corroboration_radius_m);
  f_corr := LEAST(v_corr, cfg.corroboration_saturation)::NUMERIC / cfg.corroboration_saturation;

  IF r.user_id IS NULL THEN
    v_trust := cfg.anonymous_trust;
  ELSE
    SELECT trust_score INTO v_trust FROM public.users WHERE id = r.user_id;
    v_trust := COALESCE(v_trust, cfg.anonymous_trust);
  END IF;

  v_level := public.fn_forecast_level_at(r.geom, r.created_at, cfg.corroboration_radius_m);
  -- level 1 → 0, 2 → 0.4, 3 → 0.7, 4–5 → 1
  f_fc := CASE v_level WHEN 1 THEN 0 WHEN 2 THEN 0.4 WHEN 3 THEN 0.7 WHEN 4 THEN 1 WHEN 5 THEN 1 END;

  IF v_level IS NULL THEN
    w_sum := cfg.weight_valley + cfg.weight_corroboration + cfg.weight_trust;
    v_score := 100 * (cfg.weight_valley * f_valley + cfg.weight_corroboration * f_corr + cfg.weight_trust * v_trust) / w_sum;
  ELSE
    v_score := cfg.weight_valley * f_valley + cfg.weight_corroboration * f_corr
             + cfg.weight_trust * v_trust + cfg.weight_forecast * f_fc;
  END IF;
  v_score := ROUND(v_score, 2);

  UPDATE public.reports SET
    valley_id           = CASE WHEN f_valley > 0 THEN v_id END,
    valley_distance_m   = ROUND(v_dist::NUMERIC, 1),
    corroboration_count = v_corr,
    forecast_level      = v_level,
    confidence_score    = v_score,
    status        = CASE WHEN status = 'pending' AND v_score >= cfg.auto_verify_threshold
                         THEN 'verified' ELSE status END,
    auto_verified = auto_verified OR (status = 'pending' AND v_score >= cfg.auto_verify_threshold)
  WHERE id = r.id
  RETURNING * INTO r;

  RETURN r;
END $$;

-- ───────────── Martin tiles: reaches coloured by the current forecast ─────────────
CREATE OR REPLACE FUNCTION public.stream_risk_tiles(z INTEGER, x INTEGER, y INTEGER, query_params JSON DEFAULT '{}'::JSON)
RETURNS BYTEA
LANGUAGE sql STABLE PARALLEL SAFE AS $$
  WITH latest AS (
    SELECT DISTINCT ON (region_id) id, region_id FROM public.forecast_runs
    WHERE kind = 'forecast' ORDER BY region_id, created_at DESC
  )
  SELECT ST_AsMVT(t, 'stream_risk', 4096, 'geom')
  FROM (
    SELECT s.id, s.upstream_km2, COALESCE(sm.max_level, 1) AS max_level, sm.time_of_max,
           ST_AsMVTGeom(ST_Transform(s.geom, 3857), ST_TileEnvelope(z, x, y), 4096, 64, TRUE) AS geom
    FROM public.streams s
    LEFT JOIN latest l ON l.region_id = s.region_id
    LEFT JOIN public.stream_forecast_summary sm ON sm.run_id = l.id AND sm.stream_id = s.id
    WHERE s.geom && ST_Transform(ST_TileEnvelope(z, x, y), 4326)
      AND s.upstream_km2 >= CASE WHEN z < 10 THEN 20 WHEN z < 12 THEN 5 ELSE 1 END
  ) t;
$$;

-- ───────────── lockdown (same policy as 004) ─────────────
ALTER TABLE public.regions                 ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.rain_points             ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.streams                 ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.catchments              ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.flood_zones             ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.stream_rain_weights     ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.forecast_runs           ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.forecast_rain           ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.stream_forecasts        ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.stream_forecast_summary ENABLE ROW LEVEL SECURITY;
REVOKE EXECUTE ON FUNCTION public.fn_forecast_level_at(GEOMETRY, TIMESTAMPTZ, INTEGER) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.fn_score_report(BIGINT) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.stream_risk_tiles(INTEGER, INTEGER, INTEGER, JSON) FROM PUBLIC;
DO $$
DECLARE r TEXT;
BEGIN
  FOREACH r IN ARRAY ARRAY['anon', 'authenticated'] LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = r) THEN
      EXECUTE format('REVOKE ALL ON ALL TABLES    IN SCHEMA public FROM %I', r);
      EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA public FROM %I', r);
      EXECUTE format('REVOKE ALL ON ALL FUNCTIONS IN SCHEMA public FROM %I', r);
    END IF;
  END LOOP;
END $$;
INSERT INTO public.schema_migrations (name) VALUES ('006_forecast.sql') ON CONFLICT DO NOTHING;

COMMIT;
